// CorrectRoundConfig 本地改写轮次配置（纯本地、不调 LLM）。机械修复 QA 报出的高频安全问题子集。
// 无 backend_id / batch_size / max_words_per_batch / retry；不分批、无外部 I/O、无重试。
// 规则按 rules 顺序执行，首个生效即停（不叠加）。
// 是否执行由轮次是否出现在 rounds 数组决定（与其他轮次一致，无 round 级 enabled 开关）。
type CorrectRoundConfig struct {
	// Rules 启用的改写规则，按顺序执行。至少 1 条且 Name 必须在白名单。
	Rules []CorrectRuleConfig `json:"rules"`
}

// CorrectRuleConfig defines model for CorrectRuleConfig.
type CorrectRuleConfig struct {
	Enabled *bool `json:"enabled,omitempty"`

	// Name 规则名（白名单）。首发仅 punctuation_missing_wrap：机械修复 punctuation_missing 报出
	// 的"译文丢失源文引号包裹"的安全子集（单 span、源首尾为配对引号、译文无该引号）。
	// 另支持 punctuation_wrap_loss_wrap：修复 punctuation_wrap_loss 报出的"译文丢失源文外层引号包裹"（单 span、源首尾配对引号、译文首尾无引号）。
	// width_mix_normalize：修复 width_mix 报出的全半角混用——CJK 译文把 9 个零歧义半角标点
	// （! ? , ; : ( ) [ ]）转全角（数字双侧的 , : 与数字前缀的 !? run 豁免，保留 1,000/12:30/5! 原样），
	// 拉丁译文把全角字符（FF01-FF5E，含全角字母数字）转回半角。
	Name CorrectRuleConfigName `json:"name"`
}

// CorrectRuleConfigName 规则名（白名单）。首发仅 punctuation_missing_wrap：机械修复 punctuation_missing 报出
// 的"译文丢失源文引号包裹"的安全子集（单 span、源首尾为配对引号、译文无该引号）。
// 另支持 punctuation_wrap_loss_wrap：修复 punctuation_wrap_loss 报出的"译文丢失源文外层引号包裹"（单 span、源首尾配对引号、译文首尾无引号）。
// width_mix_normalize：修复 width_mix 报出的全半角混用——CJK 译文把 9 个零歧义半角标点
// （! ? , ; : ( ) [ ]）转全角（数字双侧的 , : 与数字前缀的 !? run 豁免，保留 1,000/12:30/5! 原样），
// 拉丁译文把全角字符（FF01-FF5E，含全角字母数字）转回半角。
type CorrectRuleConfigName string

